import os
import boto3
from collections import defaultdict

def extract_tables(payload, config=None):
    config = config or {}
    textract_client = boto3.client("textract")
    response = textract_client.analyze_document(
        Document={'Bytes': payload},
        FeatureTypes=['TABLES']
    )
    blocks_by_id = {block['Id']: block for block in response['Blocks']}
    tables_data = []

    table_blocks = [block for block in response['Blocks'] if block['BlockType'] == 'TABLE']

    for table in table_blocks:
        cells_by_row = defaultdict(list)
        for rel in table.get('Relationships', []):
            if rel['Type'] == 'CHILD':
                for cell_id in rel['Ids']:
                    cell = blocks_by_id.get(cell_id)
                    if not cell or cell['BlockType'] != 'CELL':
                        continue

                    text = ''
                    if 'Relationships' in cell:
                        for word_rel in cell['Relationships']:
                            if word_rel['Type'] == 'CHILD':
                                for word_id in word_rel['Ids']:
                                    word = blocks_by_id.get(word_id)
                                    if word and word['BlockType'] == 'WORD':
                                        text += word['Text'] + ' '

                    cells_by_row[cell['RowIndex']].append({
                        'text': text.strip(),
                        'col_index': cell['ColumnIndex']
                    })

        if not cells_by_row:
            tables_data.append([])
            continue

        max_row = max(cells_by_row.keys())
        reconstructed_table = []
        for i in range(1, max_row + 1):
            row_cells = sorted(cells_by_row.get(i, []), key=lambda c: c['col_index'])
            reconstructed_table.append([cell['text'] for cell in row_cells])
        tables_data.append(reconstructed_table)

    result = tables_data
    return result
